);

CREATE VIEW "v_invoice_status_totals" AS
  SELECT
    i."status" AS "status",
    COUNT(i."id") AS "invoices",
    SUM(i."amountCents") AS "totalCents",
    SUM(CASE WHEN i."status" = 'PAID' THEN i."amountCents" END) AS "paidCents"
  FROM "invoices" i
  GROUP BY i."status";

CREATE VIEW "v_invoices_by_month" AS
  SELECT
    date(i."issuedOn", 'start of month') AS "issuedOnMonth",
    COUNT(i."id") AS "invoices",
    SUM(i."amountCents") AS "totalCents"
  FROM "invoices" i
  GROUP BY date(i."issuedOn", 'start of month');

CREATE VIEW "v_invoice_totals" AS
  SELECT
    COUNT(i."id") AS "invoices",
    SUM(i."amountCents") AS "totalCents",
    CAST(COUNT(CASE WHEN i."status" = 'PAID' THEN i."id" END) AS REAL) / NULLIF(COUNT(i."id"), 0) AS "paidShare"
  FROM "invoices" i;

CREATE VIEW "v_invoice_calendar" AS
  SELECT
    date(i."issuedOn") AS "issuedOnDay",
    date(i."issuedOn", 'start of month') AS "issuedOnMonth",
    COUNT(i."id") AS "invoices",
    SUM(i."amountCents") AS "totalCents"
  FROM "invoices" i
  GROUP BY date(i."issuedOn"), date(i."issuedOn", 'start of month');

CREATE VIEW "v_invoice_disputes" AS
  SELECT
    i."disputed" AS "disputed",
    COUNT(i."id") AS "invoices",
    COUNT(CASE WHEN i."amountCents" >= 60000 THEN i."id" END) AS "bigInvoices"
  FROM "invoices" i
  GROUP BY i."disputed";

CREATE VIEW "v_product_revenue" AS
  SELECT
    p."id" AS "productId",
    p."name" AS "productName",
    COUNT(s."id") AS "sales",
    SUM(s."amountCents") AS "revenueCents",
    COALESCE(SUM(s."amountCents"), 0) AS "revenueOrZero"
  FROM "products" p
  LEFT OUTER JOIN "sales" s ON p."id" = s."productId"
  GROUP BY p."id", p."name";

CREATE VIEW "v_sales_by_category" AS
  SELECT
    c."name" AS "categoryName",
    COUNT(s."id") AS "sales",
    SUM(s."amountCents") AS "revenueCents",
    MAX(s."amountCents") AS "maxCents",
    COUNT(CASE WHEN s."amountCents" >= 10000 THEN s."id" END) AS "largeSales"
  FROM "sales" s
  INNER JOIN "products" p ON p."id" = s."productId"
  LEFT OUTER JOIN "categories" c ON c."id" = p."categoryId"
  GROUP BY c."name";

CREATE VIEW "v_sales_by_sku" AS
  SELECT
    p."sku" AS "productSku",
    COUNT(s."id") AS "sales",
    SUM(s."amountCents") AS "revenueCents"
  FROM "sales" s
  INNER JOIN "products" p ON p."id" = s."productId"
  GROUP BY p."sku";

CREATE VIEW "v_product_refunds" AS
  SELECT
    p."id" AS "productId",
    p."name" AS "productName",
    COUNT(s."id") AS "sales",
    MAX(s."refunded") AS "hasRefund",
    COALESCE(MAX(s."refunded"), 0) AS "hasRefundOrFalse"
  FROM "products" p
  LEFT OUTER JOIN "sales" s ON p."id" = s."productId"
  GROUP BY p."id", p."name";

CREATE VIEW "v_tickets_by_tags" AS
  SELECT
    t."tags" AS "tags",
    t."attrs" AS "attrs",
    COUNT(t."id") AS "tickets"
  FROM "tickets" t
  GROUP BY t."tags", t."attrs";

CREATE VIEW "v_reading_log" AS
  SELECT
    r."seq" AS "seq",
    COUNT(r."id") AS "readings"
  FROM "readings" r
  GROUP BY r."seq";
